public final class ClaimNameValidator {

    public String validateName(String name) {
        if (name == null) {
            return "Claimant name is required.";
        }
        String trimmed = name.trim();
        if (trimmed.isEmpty()) {
            return "Claimant name is required.";
        }
        if (trimmed.length() < 2) {
            return "Claimant name must be at least 2 characters.";
        }
        if (trimmed.length() > 80) {
            return "Claimant name must be at most 80 characters.";
        }
        return null;
    }
}

